package com.campusnova.service; import com.campusnova.dto.LoginRequest; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.stereotype.Service; import java.util.*;
@Service public class AuthService { private final Set<String> tokens=Collections.synchronizedSet(new HashSet<String>()); private final BCryptPasswordEncoder encoder=new BCryptPasswordEncoder(); private final String demoHash=encoder.encode("nova2026"); public String login(LoginRequest r){if("admin".equals(r.getUsername())&&encoder.matches(r.getPassword(),demoHash)){String t=UUID.randomUUID().toString();tokens.add(t);return t;} throw new SecurityException("Invalid administrator credentials");} public boolean valid(String token){return token!=null&&tokens.contains(token);} public void logout(String token){tokens.remove(token);} }
